F=lambda s,r,c:np.array(s,dtype=float).reshape(r,c)/1e3
WE=F([-610,-106,-1610,376,1113,-182,-158,20,-69,-266,-247,275,437,199,-237,248,955,-1091,-315,-827,404,419,187,952,-180,2180,464,-352,449,1144,-83,216,-1062,92,1343,285,441,-197,402,-92,-2012,-40,-720,-1303,331,15,907,290],6,8)
