def model(x,iv):
 E=WE[x]+WP
 S=(E@A0)@np.swapaxes(E,1,2);a=np.exp(S-S.max(2)[:,:,None]);a/=a.sum(2)[:,:,None]
 r=E+iv('pat',a.reshape(-1,36)).reshape(-1,6,6)@(E@P0)
 q=r[:,5]@A1;t=(q[:,None]*r).sum(2);b=np.exp(t-t.max(1)[:,None]);b/=b.sum(1)[:,None]
 z=r[:,5]@WU+(iv('a1',b)[:,:,None]*(r@M)).sum(1)
 return iv('sc',np.c_[z,0*z[:,:2]-[3,5]])
